-- ============================================================
-- GSO PRIMS — Sprint 11 fix-up (idempotent, safe to run repeatedly)
-- Re-applies parts the first run may have skipped: stock card +
-- audit seeds, counters, storage bucket & policies, realtime,
-- and the audit triggers.
-- ============================================================

-- counters (no-op when already present)
on conflict (prefix) do nothing;

-- stock_card
-- audit_logs

-- storage bucket + policies (each guarded)
on conflict (id) do nothing;

do $$ begin
  create policy attachments_read on storage.objects for select using (bucket_id = 'attachments');
exception when others then null; end $$;
do $$ begin
  create policy attachments_insert_auth on storage.objects for insert to authenticated with check (bucket_id = 'attachments');
exception when others then null; end $$;
do $$ begin
  create policy attachments_insert_anon on storage.objects for insert to anon with check (bucket_id = 'attachments');
exception when others then null; end $$;
do $$ begin
  create policy attachments_delete_auth on storage.objects for delete to authenticated using (bucket_id = 'attachments');
exception when others then null; end $$;

-- realtime publication (each table guarded)
do $$ begin alter publication supabase_realtime add table public.purchase_requests; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.purchase_orders; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.ris_requests; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.inventory_items; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.stock_card; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.reservations; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.audit_logs; exception when others then null; end $$;

-- audit triggers (recreated cleanly)
drop trigger if exists audit_purchase_requests on public.purchase_requests;
drop trigger if exists audit_purchase_orders on public.purchase_orders;
drop trigger if exists audit_ris_requests on public.ris_requests;
drop trigger if exists audit_inventory_items on public.inventory_items;
drop trigger if exists audit_reservations on public.reservations;
create trigger audit_purchase_requests after insert or update or delete on public.purchase_requests
  for each row execute function public.log_audit();
create trigger audit_purchase_orders after insert or update or delete on public.purchase_orders
  for each row execute function public.log_audit();
create trigger audit_ris_requests after insert or update or delete on public.ris_requests
  for each row execute function public.log_audit();
create trigger audit_inventory_items after insert or update or delete on public.inventory_items
  for each row execute function public.log_audit();
create trigger audit_reservations after insert or update or delete on public.reservations
  for each row execute function public.log_audit();

-- report back
select
  (select count(*) from public.stock_card) as stock_card_rows,
  (select count(*) from public.audit_logs) as audit_rows,
  (select count(*) from storage.buckets where id = 'attachments') as bucket_ok;
